Convert SQL to PySpark:
```sql
select *
from (
    select
        status,
        plan,
        monthly_fee
    from subscriptions
) src
pivot (
    max(monthly_fee) as amount,
    count(1) as n
    for plan in ('premium' as premium, 'standard' as standard)
);
```

Convert SQL to PySpark:
```sql
select *
from (
    select
        customer_id,
        plan,
        monthly_fee
    from subscriptions
) src
pivot (
    sum(monthly_fee)
    for plan in ('premium', 'enterprise', 'basic')
);
```

Convert SQL to PySpark:
```sql
select product_id, quantity_range
from (
    select product_id, max(quantity) - min(quantity) as quantity_range
    from inventory
    group by product_id
) as t
where quantity_range < 80;
```

Convert SQL to PySpark:
```sql
select account_type, avg_balance, balance_range
from (
    select account_type, round(avg(balance), 2) avg_balance, max(balance) - min(balance) balance_range
    from accounts
    group by account_type
) s
where avg_balance < 29;
```

Convert SQL to PySpark:
```sql
SELECT * FROM (
    SELECT segment, country, credit_limit FROM customers
) PIVOT (
    SUM(credit_limit) FOR country IN ('TH', 'US', 'SG')
);
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by store_id order by quantity desc, id) as rank_in_group
    from inventory
) x
where rank_in_group = 1;
```

Convert SQL to PySpark:
```sql
select *
from (
    select date_format(txn_time, 'yyyy-MM') as txn_month, count(amount) as amount_count
    from transactions
    group by date_format(txn_time, 'yyyy-MM')
) as x
where amount_count < 5;
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by status order by paid_at, id) as row_num
    from payments
) as r
where row_num <= 3
order by method, amount desc;
```

