);
```

Convert SQL to PySpark:
```sql
select plan, active_count, avg_monthly_fee
from (
    select plan, count(case when status = 'ACTIVE' then 1 end) as active_count, avg(monthly_fee) as avg_monthly_fee
    from subscriptions
    group by plan
) as x
where avg_monthly_fee > 120;
```

Convert SQL to PySpark:
```sql
select sale_month, min_revenue, min_units
from (
    select date_format(sale_date, 'yyyy-MM') as sale_month, min(revenue) as min_revenue, min(units) as min_units
    from store_sales
    group by date_format(sale_date, 'yyyy-MM')
) as sub
where min_revenue > 1700;
```

